fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    host::display::clear(0x000000);
    host::display::draw_line(0, py, w - 1, py, 0x00ff00);
    host::display::draw_line(px, 0, px, h - 1, 0x00ff00);
    host::display::draw_number(4, 4, px, 0xffffff, 1);
    host::display::draw_number(52, 4, py, 0xffffff, 1);
    host::display::present();
}
